<?php

namespace App\Models;

use App\Enums\OccurrenceStatus;
use Carbon\CarbonImmutable;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * One concrete instance of an event. All instants are UTC (timestamptz).
 *
 * Rows are generated by App\Calendar\OccurrenceGenerator, never created by hand.
 *
 * @property int $id
 * @property int $event_id
 * @property string $recurrence_key
 * @property CarbonImmutable $starts_at
 * @property CarbonImmutable|null $ends_at
 * @property CarbonImmutable $expires_at
 * @property OccurrenceStatus $status
 * @property-read Event $event
 */
#[Fillable(['event_id', 'recurrence_key', 'starts_at', 'ends_at', 'expires_at', 'status'])]
class EventOccurrence extends Model
{
    /**
     * @var array<string, mixed>
     */
    protected $attributes = [
        'status' => 'scheduled',
    ];

    /**
     * @return BelongsTo<Event, $this>
     */
    public function event(): BelongsTo
    {
        return $this->belongsTo(Event::class);
    }

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'status' => OccurrenceStatus::class,
            'starts_at' => 'immutable_datetime',
            'ends_at' => 'immutable_datetime',
            'expires_at' => 'immutable_datetime',
            'created_at' => 'immutable_datetime',
            'updated_at' => 'immutable_datetime',
        ];
    }
}
